def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    # Endgame: last round always defect
    if n >= 99:
        return 'D'

    # Detect unconditional cooperator and exploit
    if opp_d == 0:
        if n < 3:
            return 'C'
        if n == 3:
            return 'D'
        if opp[-1] == 'C':
            return 'D'
        else:
            return 'C'

    # If opponent always defects, defect
    if opp_c == 0:
        return 'D'

    last_opp = opp[-1]

    if last_opp == 'C':
        return 'C'

    # Opponent defected last move. Count consecutive defections.
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            consec_d += 1
        else:
            break

    # Long defection streak: mostly defect, but test occasionally to recover
    if consec_d >= 6:
        if n % 10 == 0:
            return 'C'
        return 'D'

    # Short defection streak: forgive based on overall cooperation rate
    if opp_c * 2 >= n:
        if rng.random() < 0.5:
            return 'C'
        return 'D'
    else:
        if n % 7 == 0:
            return 'C'
        return 'D'
